package io.github.rebrowser.continuity;

import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
import java.lang.reflect.Modifier;
import org.junit.Test;

/** Real HOST filesystems only. Not Android own-path/key/consent/source qualification. */
public final class FirstSetupFilesystemTest {
    private interface Work {void run(Path root)throws Exception;}
    private void withRoot(Work work)throws Exception{
        Path root=Files.createTempDirectory("first-setup-");
        try{work.run(root);}finally{try(java.util.stream.Stream<Path> paths=Files.walk(root)){for(Path p:(Iterable<Path>)paths.sorted(Comparator.reverseOrder())::iterator)Files.deleteIfExists(p);}}
    }
    @Test public void boundedEmptyNativeDirectoryEnvelopeAccepted()throws Exception{withRoot(root->{for(String d:new String[]{"cache","code_cache","files","no_backup","shared_prefs","databases"})Files.createDirectory(root.resolve(d));assertEquals(7,SourceBootstrap.inspectEmptyRoot(root,false).size());});}
    @Test public void absentMarkerIsNotFreshWhenPrivateFilesExist()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("files"));Files.write(root.resolve("files/private"),new byte[]{1});assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void priorOwnedEpochEvenEmptyBlocksFirstSetup()throws Exception{withRoot(root->{Files.createDirectories(root.resolve("no_backup/owned-epochs-v1"));assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void existingBootstrapLockBlocksFreshNotRepaired()throws Exception{withRoot(root->{Files.createDirectories(root.resolve("no_backup/source-bootstrap-v1"));Files.write(root.resolve("no_backup/source-bootstrap-v1/source-continuity.lock"),new byte[0]);assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));assertTrue(Files.exists(root.resolve("no_backup/source-bootstrap-v1/source-continuity.lock")));});}
    @Test public void unknownRootEntryBlocksEvenIfEmpty()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("unknown"));assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void symlinkRootRejected()throws Exception{withRoot(root->{Path link=root.resolve("cache");Files.createSymbolicLink(link,root);assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(link,false));});}
    @Test public void symlinkAllowedDirectoryRejected()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("files"));Files.createSymbolicLink(root.resolve("cache"),root.resolve("files"));assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void regularFileUsingAllowedDirectoryNameRejected()throws Exception{withRoot(root->{Files.write(root.resolve("cache"),new byte[0]);assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void nonemptyCacheNotSilentlyClassifiedAsSafe()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("code_cache"));Files.write(root.resolve("code_cache/unknown"),new byte[0]);assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void preparedEnvelopeIsNotAFreshInventory()throws Exception{withRoot(root->{Files.createDirectories(root.resolve("no_backup/owned-epochs-v1"));assertEquals(2,SourceBootstrap.inspectEmptyRoot(root,true).size());assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));});}
    @Test public void rootAndChildDirectoryReplacementChangesExactSnapshot()throws Exception{withRoot(root->{Path files=Files.createDirectory(root.resolve("files"));Map<Path,Object> before=SourceBootstrap.inspectEmptyRoot(root,false);Files.move(files,root.resolve("saved"));Files.createDirectory(files);Map<Path,Object> after=new LinkedHashMap<>(before);after.put(files,Files.readAttributes(files,java.nio.file.attribute.BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS).fileKey());assertNotEquals(before,after);});}
    @Test public void boundedExactCiphertextReaderActuallyReachesEof()throws Exception{withRoot(root->{Path file=root.resolve("record");byte[] expected={1,2,3};Files.write(file,expected);assertArrayEquals(expected,SourceBootstrap.readExactSmall(file,3));});}
    @Test public void oversizedSymlinkAndDirectoryCiphertextRejected()throws Exception{withRoot(root->{Path file=root.resolve("record");Files.write(file,new byte[4]);assertThrows(java.io.IOException.class,()->SourceBootstrap.readExactSmall(file,3));Path link=root.resolve("link");Files.createSymbolicLink(link,file);assertThrows(java.io.IOException.class,()->SourceBootstrap.readExactSmall(link,10));assertThrows(java.io.IOException.class,()->SourceBootstrap.readExactSmall(root,10));});}
    @Test public void privateConsentCannotBeCallerConstructedOrSerialized(){assertEquals(0,SourceBootstrap.FreshConsent.class.getConstructors().length);assertFalse(java.io.Serializable.class.isAssignableFrom(SourceBootstrap.FreshConsent.class));for(java.lang.reflect.Constructor<?> c:SourceBootstrap.FreshConsent.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(c.getModifiers()));}
    @Test public void exactLibraryMarkerAllowedOnlyWithActualPackageMetadata()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("files"));byte[] marker=java.nio.ByteBuffer.allocate(24).putInt(1).putInt(327680).putLong(1234).putLong(1294).array();Files.write(root.resolve("files/profileInstalled"),marker);assertEquals(2,SourceBootstrap.inspectEmptyRoot(root,false,1234).size());assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false));assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false,1235));});}
    @Test public void libraryMarkerDoesNotExemptOtherPrivateFiles()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("files"));Files.write(root.resolve("files/profileInstalled"),java.nio.ByteBuffer.allocate(24).putInt(1).putInt(0).putLong(1234).putLong(0).array());Files.write(root.resolve("files/private"),new byte[0]);assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false,1234));});}
    @Test public void markerFormatVersionResultAndNegativeSizeRejected(){byte[] good=java.nio.ByteBuffer.allocate(24).putInt(1).putInt(0).putLong(1234).putLong(0).array();assertTrue(SourceBootstrap.validProfileInstallerMarker(good,1234));for(int offset:new int[]{0,4}){byte[] bad=good.clone();java.nio.ByteBuffer.wrap(bad).putInt(offset,9);assertFalse(SourceBootstrap.validProfileInstallerMarker(bad,1234));}assertFalse(SourceBootstrap.validProfileInstallerMarker(Arrays.copyOf(good,25),1234));java.nio.ByteBuffer.wrap(good).putLong(16,-1);assertFalse(SourceBootstrap.validProfileInstallerMarker(good,1234));}
    @Test public void symlinkLibraryMarkerNeverGetsException()throws Exception{withRoot(root->{Files.createDirectory(root.resolve("files"));Path marker=root.resolve("files/profileInstalled");Files.createSymbolicLink(marker,marker);assertThrows(java.io.IOException.class,()->SourceBootstrap.inspectEmptyRoot(root,false,1234));});}
    @Test public void missingNativeSetupInputsRejectBeforeAnyAndroidProvider(){assertThrows(SecurityException.class,()->SourceBootstrap.requestFirstSetup(null,null,null));assertThrows(SecurityException.class,()->io.github.rebrowser.crypto.InstallKeyStore.createForFirstSetup(null));assertThrows(IllegalArgumentException.class,()->io.github.rebrowser.crypto.DataKeyVault.createForFirstSetup(null));}
}
